const CATS = ["Verduras y Hortalizas","Carnes y Mariscos","Frutas","LÃ¡cteos, Quesos y Hierbas","Masas y bases","Otros"];
const STORE_KEY = "rrbb_ingredients_v1";
const STATE_KEYS = ["entero","mitad","picado"];

function hasLS(){ try{ const k="__t"; localStorage.setItem(k,"1"); localStorage.removeItem(k); return true; }catch(e){ return false; } }
const LS = hasLS();
function slug(s){ return (s||"").toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'') || 'ing'; }
function uid(base){ let s=slug(base), n=s, i=2; const ids=new Set(LIB.map(x=>x.id)); while(ids.has(n)) n=s+'-'+(i++); return n; }
function toast(m){ const t=document.getElementById('toast'); t.textContent=m; t.classList.add('show'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('show'),1900); }

let LIB, DRIZ, BASES, STYLES;
function loadStore(){ if(LS){ const raw=localStorage.getItem(STORE_KEY); if(raw){ try{ return JSON.parse(raw); }catch(e){} } } return null; }
function loadLib(){ const s=loadStore(); if(s&&Array.isArray(s.ingredients)) return s.ingredients; return JSON.parse(JSON.stringify(START_LIB.ingredients)); }
function seedDriz(){ return [
  {id:'miel',name:'Miel',color:'#e0a52a',alpha:0.85},
