    {id:'molde',name:'Molde',wcm:36,hcm:36,ar:1,shape:'circle',sauceInset:{x:0.13,y:0.13},doughBox:{x0:0,y0:0.07,x1:1,y1:0.93},sprites:{0:'',1:''}},
    {id:'plancha',name:'Plancha',wcm:25,hcm:40,ar:0.8967,shape:'oval',sauceInset:{x:0.15,y:0.075},doughBox:{x0:0,y0:0,x1:1,y1:1},sprites:{0:'',1:''}}
  ];
}
function loadStyles(){
  const s=loadStore();
  if(s&&Array.isArray(s.styles)&&s.styles.length) return s.styles;
  return (START_LIB&&Array.isArray(START_LIB.styles)&&START_LIB.styles.length)?JSON.parse(JSON.stringify(START_LIB.styles)):seedStyles();
}
function libPayload(){ return {version:1, ingredients:LIB, drizzles:DRIZ, bases:BASES, styles:STYLES}; }
let _quiet=true, _published=null, _dirty=false, _pubDoc=null;
function saveLib(){ if(LS){ try{ localStorage.setItem(STORE_KEY, JSON.stringify(libPayload())); }catch(e){} } if(!_quiet){ _dirty=true; setNote('draft'); } }
LIB = loadLib(); DRIZ = loadDriz(); BASES = loadBases(); STYLES = loadStyles();

// ---- category selects ----
function fillCats(){
  const cats = Array.from(new Set([...CATS, ...LIB.map(i=>i.cat).filter(Boolean)]));
  const cf=document.getElementById('catFilter'); cf.innerHTML='<option value="">Todas las categorÃ­as</option>'+cats.map(c=>`<option>${c}</option>`).join('');
  const fc=document.getElementById('fCat'); fc.innerHTML=cats.map(c=>`<option>${c}</option>`).join('');
  const pc=document.getElementById('pickCat'); const fcats=Array.from(new Set(FRAMES.map(f=>f.cat)));
  pc.innerHTML='<option value="">Todas</option>'+fcats.map(c=>`<option>${c}</option>`).join('');
}

// ---- library grid ----
function renderLib(){
  const q=document.getElementById('search').value.trim().toLowerCase();
  const cat=document.getElementById('catFilter').value;
  const g=document.getElementById('libGrid'); g.innerHTML='';
  const nw=document.createElement('div'); nw.className='card new'; nw.innerHTML='<div style="font-size:30px;line-height:1">ï¼‹</div><div>Nuevo ingrediente</div>';
  nw.onclick=()=>openEdit(null); g.appendChild(nw);
  let shown=0;
  LIB.filter(i=>(!cat||i.cat===cat) && (!q||i.name.toLowerCase().includes(q))).forEach(ing=>{
    shown++;
    const c=document.createElement('div'); c.className='card';
    const e=ing.states.entero||{};
    c.innerHTML=`<div class="thumb"><img src="${e.uri||''}"></div>
      <div class="nm">${ing.name}</div><div class="cat">${ing.cat||''}</div>
      <div class="badges">
        <span class="badge on">E</span>
        <span class="badge ${ing.states.mitad?'on':''}">M</span>
        <span class="badge ${ing.states.picado?'on':''}">P</span>
      </div>`;
    c.onclick=()=>openEdit(ing);
    g.appendChild(c);
  });
  document.getElementById('count').textContent = `${LIB.length} ingredientes`+(shown!==LIB.length?` Â· ${shown} visibles`:'');
}

// ---- edit panel ----
let editing=null, isNew=false;
function openEdit(ing){
  isNew=!ing;
  editing = ing ? JSON.parse(JSON.stringify(ing)) : {id:null, name:'', cat:document.getElementById('fCat').value||CATS[0], scale:1, states:{}};
  document.getElementById('editTitle').textContent = isNew?'Nuevo ingrediente':'Editar ingrediente';
  document.getElementById('fName').value=editing.name;
  document.getElementById('fCat').value=editing.cat||CATS[0];
  document.getElementById('fScale').value=editing.scale||1;
  document.getElementById('fScaleOut').textContent=(editing.scale||1).toFixed(2)+'Ã—';
  document.getElementById('fOpacity').value=(editing.opacity==null?1:editing.opacity);
  document.getElementById('fOpacityOut').textContent=Math.round((editing.opacity==null?1:editing.opacity)*100)+'%';
  document.getElementById('btnDelete').style.display = isNew?'none':'';
  renderSlots();
  document.getElementById('editPanel').classList.add('show');
}
function closeEdit(){ document.getElementById('editPanel').classList.remove('show'); editing=null; }
function hexToHsl(hex){
  let r=parseInt(hex.slice(1,3),16)/255,g=parseInt(hex.slice(3,5),16)/255,b=parseInt(hex.slice(5,7),16)/255;
  const mx=Math.max(r,g,b),mn=Math.min(r,g,b); let h,s,l=(mx+mn)/2;
  if(mx===mn){h=s=0;} else { const dd=mx-mn; s=l>0.5?dd/(2-mx-mn):dd/(mx+mn);
    h=mx===r?((g-b)/dd+(g<b?6:0)):mx===g?((b-r)/dd+2):((r-g)/dd+4); h/=6; }
  return {h,s};
}
function hslToRgb(h,s,l){
  if(s===0){ const v=Math.round(l*255); return [v,v,v]; }
  const q=l<0.5?l*(1+s):l+s-l*s, p=2*l-q;
  const t=x=>{ if(x<0)x+=1; if(x>1)x-=1; if(x<1/6)return p+(q-p)*6*x; if(x<1/2)return q; if(x<2/3)return p+(q-p)*(2/3-x)*6; return p; };
  return [Math.round(t(h+1/3)*255),Math.round(t(h)*255),Math.round(t(h-1/3)*255)];
}
function tintState(k, hex){
  const st=editing.states[k]; if(!st) return;
  const img=new Image();
  img.onload=()=>{
    const cv=document.createElement('canvas'); cv.width=img.naturalWidth; cv.height=img.naturalHeight;
    const cx=cv.getContext('2d'); cx.drawImage(img,0,0);
    const d=cx.getImageData(0,0,cv.width,cv.height), p=d.data;
    const {h,s}=hexToHsl(hex);
    for(let i=0;i<p.length;i+=4){ if(p[i+3]===0) continue;
      const L=(0.299*p[i]+0.587*p[i+1]+0.114*p[i+2])/255;
      const c=hslToRgb(h,s,L); p[i]=c[0]; p[i+1]=c[1]; p[i+2]=c[2]; }
    cx.putImageData(d,0,0);
    editing.states[k]={w:cv.width,h:cv.height,uri:cv.toDataURL('image/png')};
    renderSlots(); toast('TeÃ±ido aplicado');
  };
  img.src=st.uri;
}
function renderSlots(){
  const box=document.getElementById('slots'); box.innerHTML='';
  STATE_KEYS.forEach(k=>{
    const s=editing.states[k];
    const el=document.createElement('div'); el.className='slot';
    el.innerHTML=`<div class="sthumb ${s?'':'empty'}">${s?`<img src="${s.uri}" style="opacity:${editing.opacity==null?1:editing.opacity}">`:'â€”'}</div>
      <div class="sinfo"><div class="k">${k}${k==='entero'?' (obligatorio)':''}</div>
        <div class="sbtns">
          <button data-a="pick">Elegir del juego</button>
          <button data-a="up">Subir PNG</button>
          ${k!=='entero'&&s?'<button data-a="rm" class="rm">Quitar</button>':''}
          ${s?'<button data-a="norm" title="Achicar/normalizar al tamaÃ±o estÃ¡ndar de los sprites">Normalizar</button>':''}
          ${s?`<span class="tintwrap"><input type="color" class="tintc" value="#b5502a" title="ElegÃ­ un color"><button data-a="tint">TeÃ±ir</button></span>`:''}
        </div></div>`;
    el.querySelectorAll('button').forEach(b=>b.onclick=()=>{
      const a=b.dataset.a;
      if(a==='pick') openPicker(k);
      else if(a==='up'){ uploadTarget=k; document.getElementById('fileUpload').click(); }
      else if(a==='rm'){ delete editing.states[k]; renderSlots(); }
      else if(a==='norm'){ normalizeExisting(k); }
      else if(a==='tint'){ tintState(k, el.querySelector('.tintc').value); }
    });
    box.appendChild(el);
  });
}
document.getElementById('fName').oninput=e=>{ if(editing) editing.name=e.target.value; };
document.getElementById('fCat').onchange=e=>{ if(editing) editing.cat=e.target.value; };
