  if(isNew){ editing.id=uid(editing.name); LIB.push(editing); }
  else { const i=LIB.findIndex(x=>x.id===editing.id); if(i>=0) LIB[i]=editing; }
  saveLib(); renderLib(); fillCats(); closeEdit(); toast(isNew?'Ingrediente agregado':'Guardado');
};
