};

// ---- upload custom PNG ----
let uploadTarget='entero';
const UPLOAD_MAX=42;  // tamaÃ±o estÃ¡ndar (px) al que se normaliza cada PNG subido
const SPRITE_TARGET=34;   // dimensiÃ³n mayor estÃ¡ndar (coincide con los sprites del juego)
function normalizeSprite(img){
  const iw=img.naturalWidth||img.width, ih=img.naturalHeight||img.height;
  const capN=Math.min(1, 512/Math.max(iw,ih));                 // cap para no leer imÃ¡genes enormes
  const nw=Math.max(1,Math.round(iw*capN)), nh=Math.max(1,Math.round(ih*capN));
  const t=document.createElement('canvas'); t.width=nw; t.height=nh;
  const tc=t.getContext('2d'); tc.imageSmoothingEnabled=true; tc.imageSmoothingQuality='high'; tc.drawImage(img,0,0,nw,nh);
  let x0=nw,y0=nh,x1=-1,y1=-1;                                  // recorte al Ã¡rea no transparente
  try{ const px=tc.getImageData(0,0,nw,nh).data;
    for(let y=0;y<nh;y++) for(let x=0;x<nw;x++){ if(px[(y*nw+x)*4+3]>12){ if(x<x0)x0=x; if(x>x1)x1=x; if(y<y0)y0=y; if(y>y1)y1=y; } }
  }catch(e){ x1=-1; }
  let cx0,cy0,cw,ch;
  if(x1<0){ cx0=0;cy0=0;cw=nw;ch=nh; }                         // imagen totalmente transparente
  else{ x0=Math.max(0,x0-1);y0=Math.max(0,y0-1);x1=Math.min(nw-1,x1+1);y1=Math.min(nh-1,y1+1); cx0=x0;cy0=y0;cw=x1-x0+1;ch=y1-y0+1; }
  let sc=SPRITE_TARGET/Math.max(cw,ch); sc=Math.max(0.05,Math.min(2,sc));  // normalizar dimensiÃ³n mayor a 34
  const ow=Math.max(1,Math.round(cw*sc)), oh=Math.max(1,Math.round(ch*sc));
  const o=document.createElement('canvas'); o.width=ow; o.height=oh;
  const oc=o.getContext('2d'); oc.imageSmoothingEnabled=true; oc.imageSmoothingQuality='high';
  oc.drawImage(t, cx0,cy0,cw,ch, 0,0,ow,oh);
  return {w:ow,h:oh,uri:o.toDataURL('image/png')};
}
function normalizeExisting(k){
  const s=editing&&editing.states[k]; if(!s) return;
  const img=new Image(); img.onload=()=>{ editing.states[k]=normalizeSprite(img); renderSlots(); toast('Sprite normalizado a '+SPRITE_TARGET+'px'); }; img.src=s.uri;
}
document.getElementById('fileUpload').onchange=function(){
  const f=this.files[0]; this.value=''; if(!f||!editing) return;
  const r=new FileReader();
  r.onload=()=>{ const img=new Image(); img.onload=()=>{
    editing.states[uploadTarget]=normalizeSprite(img);
    if(uploadTarget==='entero' && !editing.name) { editing.name=f.name.replace(/\.[a-z]+$/i,''); document.getElementById('fName').value=editing.name; }
    renderSlots(); toast('Sprite subido y redimensionado al estÃ¡ndar'); }; img.src=r.result; };
  r.readAsDataURL(f);
};

// ---- frame picker ----
let pickTarget='entero';
function openPicker(target){ pickTarget=target; document.getElementById('pickOverlay').classList.add('show'); renderPick(); }
function closePicker(){ document.getElementById('pickOverlay').classList.remove('show'); }
function renderPick(){
  const q=document.getElementById('pickSearch').value.trim().toLowerCase();
  const cat=document.getElementById('pickCat').value;
  const g=document.getElementById('pickGrid'); g.innerHTML='';
  const frag=document.createDocumentFragment();
  FRAMES.filter(f=>(!cat||f.cat===cat) && (!q || f.ing.toLowerCase().includes(q) || String(f.f)===q || String(f.f).padStart(3,'0').includes(q))).forEach(f=>{
    const c=document.createElement('div'); c.className='fcell';
    c.innerHTML=`<img src="${f.uri}"><div class="fl">${f.f} Â· ${f.ing}</div>`;
    c.title=`Frame ${f.f} â€” ${f.ing} (${f.w}Ã—${f.h})`;
    c.onclick=()=>{ editing.states[pickTarget]={w:f.w,h:f.h,uri:f.uri};
      if(pickTarget==='entero' && !editing.name && f.ing && f.ing!=='â€”'){ editing.name=f.ing; document.getElementById('fName').value=f.ing; }
      renderSlots(); closePicker(); };
    frag.appendChild(c);
  });
  g.appendChild(frag);
}
document.getElementById('pickSearch').oninput=renderPick;
document.getElementById('pickCat').onchange=renderPick;
document.getElementById('closePick').onclick=closePicker;
document.getElementById('pickOverlay').onclick=e=>{ if(e.target.id==='pickOverlay') closePicker(); };

// ---- import / export ----
document.getElementById('btnNew').onclick=()=>openEdit(null);
document.getElementById('search').oninput=renderLib;
document.getElementById('catFilter').onchange=renderLib;
document.getElementById('btnImport').onclick=()=>document.getElementById('fileImport').click();
document.getElementById('fileImport').onchange=function(){
  const f=this.files[0]; this.value=''; if(!f) return;
  const r=new FileReader();
  r.onload=()=>{ try{ const d=JSON.parse(r.result); if(!d.ingredients) throw 0;
    LIB=d.ingredients; if(Array.isArray(d.drizzles)) DRIZ=d.drizzles; if(Array.isArray(d.bases)) BASES=d.bases;
    saveLib(); fillCats(); (typeof renderMain==='function'?renderMain():renderLib()); toast(`Biblioteca importada (${LIB.length})`);
  }catch(e){ toast('JSON invÃ¡lido'); } };
  r.readAsText(f);
};
function download(name, text, type){
  const b=new Blob([text],{type:type||'application/json'}); const a=document.createElement('a');
  a.href=URL.createObjectURL(b); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
document.getElementById('btnExportJson').onclick=()=>{
  download('ingredients.json', JSON.stringify(libPayload(),null,1));
  toast('ingredients.json exportado');
};
document.getElementById('btnExportJs').onclick=()=>{
  const sprites = LIB.map(i=>{ const e=i.states.entero; return `{id:"${i.id}",name:${JSON.stringify(i.name)},w:${e.w},h:${e.h},uri:"${e.uri}"}`; });
  const stEntries=[];
  LIB.forEach(i=>{ const parts=[]; ['mitad','picado'].forEach(k=>{ const s=i.states[k]; if(s) parts.push(`${k}:{w:${s.w},h:${s.h},uri:"${s.uri}"}`); }); if(parts.length) stEntries.push(`"${i.id}":{${parts.join(',')}}`); });
  const js=`// Biblioteca de ingredientes Arrabbiata â€” generada por el editor de ingredientes\nconst SPRITES=[\n${sprites.join(',\n')}\n];\nconst STATES={\n${stEntries.join(',\n')}\n};\n`;
  const _nl=String.fromCharCode(10);
  const jsx = js + 'const DRIZZLES_LIB='+JSON.stringify(DRIZ||[])+';'+_nl+'const BASES_LIB='+JSON.stringify(BASES||[])+';'+_nl;
  download('pizza-lib.js', jsx, 'text/javascript');
  toast('pizza-lib.js exportado');
};

// ---- sincronizaciÃ³n con lo publicado (ingredients.json del servidor) ----
function _suppress(fn){ const p=_quiet; _quiet=true; try{ fn(); } finally{ _quiet=p; } }
function sameLib(a,b){ try{ return JSON.stringify(a)===JSON.stringify(b); }catch(e){ return false; } }
async function fetchPublished(){
  try{ const r=await fetch('ingredients.json',{cache:'no-store'});
    if(r.ok){ const d=await r.json(); if(d&&Array.isArray(d.ingredients)&&d.ingredients.length){ _pubDoc=d; return d.ingredients; } }
  }catch(e){}
  return null;
}
function adoptPublishedExtras(){ if(_pubDoc){ if(Array.isArray(_pubDoc.drizzles)) DRIZ=JSON.parse(JSON.stringify(_pubDoc.drizzles)); if(Array.isArray(_pubDoc.bases)) BASES=JSON.parse(JSON.stringify(_pubDoc.bases)); if(Array.isArray(_pubDoc.styles)) STYLES=JSON.parse(JSON.stringify(_pubDoc.styles)); } }
function setNote(state){
  const el=document.getElementById('srcNote'); if(!el) return;
  el.className='srcnote '+state; el.textContent='';
  if(state==='synced'){ _dirty=false; el.innerHTML='\u2713 En sincron\u00eda con lo publicado (<b>ingredients.json</b>).'; }
  else if(state==='offline'){ el.innerHTML='\u26a0 No pude cargar <b>ingredients.json</b> del servidor. Est\u00e1s trabajando sobre la copia local / de respaldo \u2014 verific\u00e1 antes de exportar y subir.'; }
  else if(state==='draft'){
    el.innerHTML='\u25cf Ten\u00e9s cambios locales <b>sin publicar</b>. Cuando termines, export\u00e1 el .json y subilo al servidor.';
    if(_published){ const b=document.createElement('button'); b.className='mini'; b.textContent='Descartar y volver a lo publicado'; b.onclick=discardToPublished; el.appendChild(document.createTextNode(' ')); el.appendChild(b); }
  }
}
function discardToPublished(){
  if(!_published) return;
  if(!confirm('\u00bfDescartar tus cambios locales y volver a la versi\u00f3n publicada?')) return;
  LIB=JSON.parse(JSON.stringify(_published)); _suppress(saveLib); fillCats(); renderLib(); setNote('synced'); toast('Volviste a lo publicado');
}
async function reloadFromPublished(){
  if(_dirty && !confirm('Ten\u00e9s cambios locales sin publicar. \u00bfDescartarlos y recargar lo publicado?')) return;
  const s=await fetchPublished();
  if(!s){ toast('No pude cargar lo publicado'); setNote('offline'); return; }
  _published=s; LIB=JSON.parse(JSON.stringify(s)); adoptPublishedExtras(); _suppress(saveLib); fillCats(); (typeof renderMain==='function'?renderMain():renderLib()); setNote('synced'); toast('Recargado de lo publicado');
}
async function boot(){
  fillCats(); renderLib();                       // pintar ya con lo que haya (local/respaldo)
  const hadDraft = LS && !!localStorage.getItem(STORE_KEY);
  const s = await fetchPublished();
  if(!s){ _quiet=false; setNote(hadDraft?'draft':'offline'); return; }
  _published = s;
  if(!hadDraft || sameLib(LIB, s)){              // sin borrador propio (ej: dispositivo nuevo) o igual a lo publicado
    LIB = JSON.parse(JSON.stringify(s));
    adoptPublishedExtras();
    _suppress(saveLib);                          // cachear lo publicado para uso offline
    fillCats(); (typeof renderMain==='function'?renderMain():renderLib());
    _quiet=false; setNote('synced');
  } else {                                        // hay cambios locales distintos de lo publicado: respetarlos
    _quiet=false; _dirty=true; setNote('draft');
  }
}
// ---- API cliente (guardar en el servidor) ----
const API_URL='api.php';
function apiToken(){ try{ return localStorage.getItem('rrbb_api_token')||''; }catch(e){ return ''; } }
function setApiToken(t){ try{ localStorage.setItem('rrbb_api_token', t||''); }catch(e){} }
async function apiSaveLib(){
  const payload=libPayload();
  let token=apiToken();
  for(let attempt=0; attempt<2; attempt++){
    let res;
    try{
      res=await fetch(API_URL+'?action=save-lib',{method:'POST',
        headers:{'Content-Type':'application/json','X-Auth-Token':token},
        body:JSON.stringify(payload)});
    }catch(e){ toast('No pude conectar con el servidor'); return false; }
    if(res.status===401){
      const t=prompt('Token del servidor (lo configuraste en config.php):', token);
      if(t==null) return false; token=t.trim(); setApiToken(token); continue;
    }
    let d={}; try{ d=await res.json(); }catch(e){}
    if(res.ok && d.ok){ _published=JSON.parse(JSON.stringify(LIB)); _dirty=false; setNote('synced'); toast('Guardado en el servidor ('+(d.count||LIB.length)+' ingredientes)'); return true; }
    toast('Error al guardar: '+(d.error||('HTTP '+res.status))); return false;
  }
  return false;
}
const _bs=document.getElementById('btnSaveServer'); if(_bs) _bs.onclick=apiSaveLib;
const _br=document.getElementById('btnReload'); if(_br) _br.onclick=reloadFromPublished;
boot();
</script>
<script>
/* ============ Drizzles y Bases (autorÃ­a) ============ */
(function(){
  "use strict";
  const $=id=>document.getElementById(id);
  let mode='ing';
  let editingDriz=null,isNewDriz=false,editingBase=null,isNewBase=false,    _bTexImg=null; _bSpriteImg=null;
    if(editingBase.sprite){ _bSpriteImg=new Image(); _bSpriteImg.onload=()=>drawBasePreview(editingBase); _bSpriteImg.src=editingBase.sprite; }
    if(editingBase.sprite){ setBaseType('sprite'); }

  function norm(c){ return (/^#[0-9a-fA-F]{6}$/.test(c||''))?c:'#c0432a'; }
  function uidIn(name, arr, cur){
    let base=slug(name)||'x', n=base, i=2; const ids=new Set(arr.map(x=>x.id).filter(id=>id!==cur));
    while(ids.has(n)) n=base+'-'+(i++); return n;
  }
  function _hash(s){ let h=2166136261>>>0; for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);} return h>>>0; }

  // --- previews (mismo algoritmo que el editor de pizzas) ---
  function drawDisc(c,W){ const cx=W/2,cy=W/2,R=W/2;
    c.clearRect(0,0,W,W);
    c.beginPath(); c.arc(cx,cy,R*0.96,0,7); c.fillStyle='#e6c98f'; c.fill();
    c.beginPath(); c.arc(cx,cy,R*0.82,0,7); c.fillStyle='#efdcb4'; c.fill();
  }
  function _dzShift(hex,f){
    const m=/^#?([0-9a-fA-F]{6})$/.exec(hex||''); if(!m) return hex||'#e0a52a';
    let n=parseInt(m[1],16), r=(n>>16)&255, g=(n>>8)&255, b=n&255;
    if(f>=0){ r+=(255-r)*f; g+=(255-g)*f; b+=(255-b)*f; } else { r*=(1+f); g*=(1+f); b*=(1+f); }
    return 'rgb('+Math.round(r)+','+Math.round(g)+','+Math.round(b)+')';
  }
  function drawDrizPreview(d){
    const cv=$('dPrev'); if(!cv) return; const c=cv.getContext('2d'); const W=cv.width; drawDisc(c,W);
    const cx=W/2,cy=W/2,R=W/2, rDz=R*0.72;
    const seed=_hash((d.id||d.name||'x')+'#0');
    const col=d.color||'#e0a52a', a=Math.min(1,(d.alpha==null?0.92:d.alpha)+0.05);
    const ang=(-40+(seed%22))*Math.PI/180, passes=5+(seed%3);
    const A=rDz*0.76, V=rDz*0.56, N=240, lw=Math.max(3,R*0.052), wob=(seed%7)*0.35;
    c.save(); c.beginPath(); c.arc(cx,cy,rDz*1.05,0,7); c.clip();
    c.translate(cx,cy); c.rotate(ang); c.lineCap='round'; c.lineJoin='round';
    const pth=[];
    for(let k=0;k<=N;k++){ const p=k/N; const u=A*Math.sin(p*passes*Math.PI)+Math.sin(p*Math.PI*(8+wob))*rDz*0.018; const v=-V+2*V*p; pth.push([u,v]); }
    const trace=()=>{ c.beginPath(); pth.forEach((q,k)=> k?c.lineTo(q[0],q[1]):c.moveTo(q[0],q[1])); };
    trace(); c.strokeStyle=_dzShift(col,-0.22); c.globalAlpha=a; c.shadowColor='rgba(0,0,0,.28)'; c.shadowBlur=lw*0.35; c.shadowOffsetY=lw*0.16; c.lineWidth=lw*1.12; c.stroke();
    c.shadowColor='transparent'; c.shadowBlur=0; c.shadowOffsetY=0;
    trace(); c.strokeStyle=col; c.globalAlpha=a; c.lineWidth=lw; c.stroke();
    trace(); c.strokeStyle=_dzShift(col,0.5); c.globalAlpha=a*0.55; c.lineWidth=lw*0.28; c.stroke();
    c.restore();
  }
  function drawBasePreview(b){
    const cv=$('bPrev'); if(!cv) return; const c=cv.getContext('2d'); const W=cv.width; drawDisc(c,W);
    const cx=W/2,cy=W/2,R=W/2, sr=R*0.8, a=(b.alpha==null?0.9:b.alpha);
    c.save(); c.beginPath(); c.arc(cx,cy,sr,0,7); c.clip(); c.globalAlpha=a;
    if(b.tex && _bTexImg && _bTexImg.complete && _bTexImg.naturalWidth){
      try{ const pat=c.createPattern(_bTexImg,'repeat'); c.fillStyle=pat; c.fillRect(cx-sr,cy-sr,sr*2,sr*2); }catch(e){}
    } else {
      c.fillStyle=b.color||'#c0432a'; c.beginPath(); c.arc(cx,cy,sr,0,7); c.fill();
    }
    c.restore();
  }

  // --- grids ---
  function newCard(label,fn){ const nw=document.createElement('div'); nw.className='card new';
    nw.innerHTML='<div style="font-size:30px;line-height:1">ï¼‹</div><div>'+label+'</div>'; nw.onclick=fn; return nw; }
  function renderDriz(){
    const q=$('search').value.trim().toLowerCase(); const g=$('libGrid'); g.innerHTML='';
    g.appendChild(newCard('Nuevo drizzle',()=>openDriz(null)));
    DRIZ.filter(d=>!q||(d.name||'').toLowerCase().includes(q)).forEach(d=>{
      const c=document.createElement('div'); c.className='card';
      c.innerHTML='<div class="swatch" style="background:'+(d.color||'#e0a52a')+'"></div><div class="nm">'+d.name+'</div>'+
        '<div class="cat">drizzle Â· '+Math.round((d.alpha==null?.85:d.alpha)*100)+'%</div>';
      c.onclick=()=>openDriz(d); g.appendChild(c);
    });
    $('count').textContent=DRIZ.length+' drizzles';
  }
  function renderBases(){
    const q=$('search').value.trim().toLowerCase(); const g=$('libGrid'); g.innerHTML='';
    g.appendChild(newCard('Nueva base',()=>openBase(null)));
    BASES.filter(b=>!q||(b.name||'').toLowerCase().includes(q)).forEach(b=>{
      const c=document.createElement('div'); c.className='card';
      const sty=b.tex?('background-image:url('+b.tex+');background-size:22px;background-repeat:repeat'):('background:'+(b.color||'#c0432a'));
      c.innerHTML='<div class="swatch" style="'+sty+'"></div><div class="nm">'+b.name+'</div>'+
        '<div class="cat">'+(b.tex?'textura':'color')+' Â· '+Math.round((b.alpha==null?.9:b.alpha)*100)+'%</div>';
      c.onclick=()=>openBase(b); g.appendChild(c);
    });
    $('count').textContent=BASES.length+' bases';
  }

  function closeAllPanels(){ ['editPanel','drizPanel','basePanel','stylePanel'].forEach(id=>{ const p=$(id); if(p)p.classList.remove('show'); }); }
  window.renderMain=function(){
    if(mode==='driz') renderDriz();
    else if(mode==='base') renderBases();
    else if(mode==='style') renderStyles();
    else renderLib();
  };
  function setMode(m){
    mode=m;
    document.querySelectorAll('#modeSeg button').forEach(x=>x.classList.toggle('sel',x.dataset.mode===m));
    $('catFilter').style.display = m==='ing'?'':'none';
    $('search').placeholder = m==='ing'?'Buscar ingredienteâ€¦' : m==='driz'?'Buscar drizzleâ€¦' : m==='base'?'Buscar baseâ€¦':'Buscar estilo de pizzaâ€¦';
    $('btnNew').textContent = m==='ing'?'+ Nuevo ingrediente' : m==='driz'?'+ Nuevo drizzle' : m==='base'?'+ Nueva base':'+ Nuevo estilo';
    closeAllPanels(); renderMain();
  }

  // --- editar drizzle ---
  function openDriz(d){
    closeAllPanels(); isNewDriz=!d;
    editingDriz = d? JSON.parse(JSON.stringify(d)) : {id:null,name:'',color:'#e0a52a',alpha:0.85};
    $('drizTitle').textContent=isNewDriz?'Nuevo drizzle':'Editar drizzle';
    $('dName').value=editingDriz.name; $('dColor').value=norm(editingDriz.color); $('dColorHex').value=editingDriz.color||'';
    $('dAlpha').value=(editingDriz.alpha==null?0.85:editingDriz.alpha); $('dAlphaOut').textContent=Math.round((editingDriz.alpha==null?0.85:editingDriz.alpha)*100)+'%';
    $('dDelete').style.display=isNewDriz?'none':''; drawDrizPreview(editingDriz);
    $('drizPanel').classList.add('show');
  }
  function saveDriz(){
    if(!editingDriz) return; const nm=$('dName').value.trim(); if(!nm){ toast('Ponele un nombre'); return; }
    editingDriz.name=nm; editingDriz.color=norm($('dColorHex').value.trim()||$('dColor').value); editingDriz.alpha=parseFloat($('dAlpha').value);
    if(isNewDriz){ editingDriz.id=uidIn(nm,DRIZ,null); DRIZ.push(editingDriz); }
    else { editingDriz.id=editingDriz.id||uidIn(nm,DRIZ,null); const i=DRIZ.findIndex(x=>x.id===editingDriz.id); if(i>=0)DRIZ[i]=editingDriz; else DRIZ.push(editingDriz); }
    saveLib(); closeAllPanels(); renderMain(); toast('Drizzle guardado');
  }
  function delDriz(){ if(!editingDriz||isNewDriz) return; if(!confirm('Â¿Eliminar este drizzle?')) return;
    DRIZ=DRIZ.filter(x=>x.id!==editingDriz.id); saveLib(); closeAllPanels(); renderMain(); toast('Drizzle eliminado'); }

  // --- editar base ---
  let _bSpriteImg = null;
  function setBaseType(t){
    if(!editingBase) return; editingBase._type=t;
    document.querySelectorAll('#bTypeSeg button').forEach(x=>x.classList.toggle('sel',x.dataset.type===t));
    bColorField.style.display = t==='color'?'':'none';
    bTexField.style.display = t==='tex'?'':'none';
    bSpriteField.style.display = t==='sprite'?'':'none';
    drawBasePreview(editingBase);
  }
  function _setBaseTypeLegacy(t){
    if(!editingBase) return; editingBase._type=t;
    document.querySelectorAll('#bTypeSeg button').forEach(x=>x.classList.toggle('sel',x.dataset.type===t));
    $('bColorField').style.display = t==='color'?'':'none';
    $('bTexField').style.display = t==='tex'?'':'none';
    drawBasePreview(editingBase);
  }
  function openBase(b){
    closeAllPanels(); isNewBase=!b;
    editingBase = b? JSON.parse(JSON.stringify(b)) : {id:null,name:'',color:'#c0432a',alpha:0.9};
    $('baseTitle').textContent=isNewBase?'Nueva base':'Editar base';
    $('bName').value=editingBase.name; $('bColor').value=norm(editingBase.color); $('bColorHex').value=editingBase.color||'';
    $('bAlpha').value=(editingBase.alpha==null?0.9:editingBase.alpha); $('bAlphaOut').textContent=Math.round((editingBase.alpha==null?0.9:editingBase.alpha)*100)+'%';
    $('bDelete').style.display=isNewBase?'none':'';
        _bTexImg=null; _bSpriteImg=null;
    if(editingBase.sprite){ _bSpriteImg=new Image(); _bSpriteImg.onload=()=>drawBasePreview(editingBase); _bSpriteImg.src=editingBase.sprite; }
    if(editingBase.sprite){ setBaseType('sprite'); }
    if(editingBase.tex){ _bTexImg=new Image(); _bTexImg.onload=()=>drawBasePreview(editingBase); _bTexImg.src=editingBase.tex; }
    setBaseType(editingBase.tex?'tex':'color');
    drawBasePreview(editingBase);
    $('basePanel').classList.add('show');
  }
  function saveBase(){
    if(!editingBase) return; const nm=$('bName').value.trim(); if(!nm){ toast('Ponele un nombre'); return; }
    editingBase.name=nm; editingBase.color=norm($('bColorHex').value.trim()||$('bColor').value); editingBase.alpha=parseFloat($('bAlpha').value);
        if(editingBase._type==='color'){ delete editingBase.tex; delete editingBase.sprite; }
    else if(editingBase._type==='tex'){ delete editingBase.sprite; if(!editingBase.tex){ toast('SubÃ­ una textura'); return; } }
    else if(editingBase._type==='sprite'){ delete editingBase.tex; if(!editingBase.sprite){ toast('SubÃ­ un sprite'); return; } }
    else if(!editingBase.tex){ toast('SubÃ­ una textura PNG o cambiÃ¡ a Color'); return; }
    delete editingBase._type;
    if(isNewBase){ editingBase.id=uidIn(nm,BASES,null); BASES.push(editingBase); }
    else { editingBase.id=editingBase.id||uidIn(nm,BASES,null); const i=BASES.findIndex(x=>x.id===editingBase.id); if(i>=0)BASES[i]=editingBase; else BASES.push(editingBase); }
    saveLib(); closeAllPanels(); renderMain(); toast('Base guardada');
  }
  function delBase(){ if(!editingBase||isNewBase) return; if(!confirm('Â¿Eliminar esta base?')) return;
    BASES=BASES.filter(x=>x.id!==editingBase.id); saveLib(); closeAllPanels(); renderMain(); toast('Base eliminada'); }

  // --- estilos de pizza ---
  let editingStyle = null, isNewStyle = false, stylePrevBake = 1;
  const _sImgCache = {};

  function sImgFor(uri){
    if(!uri) return null;
    let im = _sImgCache[uri];
    if(!im){ im = new Image(); im.src = uri; _sImgCache[uri] = im; }
    return im;
  }

  function renderStyles(){
    const q=search.value.trim().toLowerCase(); const g=libGrid; g.innerHTML='';
    g.appendChild(newCard('Nuevo estilo',()=>openStyle(null)));
    (STYLES||[]).filter(s=>!q||(s.name||'').toLowerCase().includes(q)).forEach(s=>{
      const c=document.createElement('div'); c.className='card styleCard';
      const prevUri=(s.sprites&&(s.sprites['1']||s.sprites['0']))||'';
      const imgHtml=prevUri?<img src="" style="width:100px;height:100px;object-fit:contain;display:block;margin:0 auto 8px;" alt="">:<div style="width:100px;height:100px;display:flex;align-items:center;justify-content:center;background:var(--crema);border-radius:50%;margin:0 auto 8px;font-size:32px;">ðŸ•</div>;
      const dim=(s.wcm===s.hcm)?(s.wcm+' cm'):(s.wcm+'Ã—'+s.hcm+' cm');
      c.innerHTML=imgHtml+<div class="nm" style="font-weight:600;font-size:14px;color:var(--ink)"></div>+
        <div class="cat" style="font-size:12px;color:var(--muted)"> Â· </div>;
      c.onclick=()=>openStyle(s); g.appendChild(c);
    });
    count.textContent=(STYLES?STYLES.length:0)+' estilos de pizza';
  }

  function drawStylePreview(st){
    const cv=sPrev; if(!cv) return;
    const c=cv.getContext('2d'); const W=cv.width, H=cv.height;
    c.clearRect(0,0,W,H);
    c.fillStyle='#f0e6d0'; c.fillRect(0,0,W,H);
    if(!st) return;

    const uri = st.sprites ? (st.sprites[stylePrevBake] || st.sprites[1-stylePrevBake] || '') : '';
    const img = sImgFor(uri);

    const pad = 20;
    const maxW = W - pad*2, maxH = H - pad*2;
    const ar = (st.wcm && st.hcm) ? (st.wcm/st.hcm) : 1;
    let dw, dh;
    if(ar >= 1){ dw = maxW; dh = maxW / ar; }
    else { dh = maxH; dw = maxH * ar; }
    const dx = (W - dw)/2, dy = (H - dh)/2;

    if(img && img.complete && img.naturalWidth){
      c.drawImage(img, dx, dy, dw, dh);
    } else if(img){
      img.onload = () => drawStylePreview(st);
    } else {
      c.fillStyle = stylePrevBake ? '#d4a259' : '#e9c88a';
      c.strokeStyle = '#b8955a'; c.lineWidth = 3;
      c.beginPath();
      if(st.shape==='rect') c.roundRect(dx, dy, dw, dh, 14);
      else c.ellipse(W/2, H/2, dw/2, dh/2, 0, 0, 7);
      c.fill(); c.stroke();
    }

    const sx = (st.sauceInset && st.sauceInset.x != null) ? st.sauceInset.x : 0.12;
    const sy = (st.sauceInset && st.sauceInset.y != null) ? st.sauceInset.y : 0.12;
    const sw = dw * (1 - 2*sx), sh = dh * (1 - 2*sy);
    const scx = dx + sx*dw, scy = dy + sy*dh;

    c.save();
    c.setLineDash([4, 4]); c.strokeStyle = '#cc1414'; c.lineWidth = 1.5;
    c.beginPath();
    if(st.shape==='rect') c.roundRect(scx, scy, sw, sh, 8);
    else c.ellipse(W/2, H/2, sw/2, sh/2, 0, 0, 7);
    c.stroke();
    c.restore();
  }

  function updateStyleSpriteStatus(){
    if(!editingStyle) return;
    const has0 = !!(editingStyle.sprites && editingStyle.sprites['0']);
    const has1 = !!(editingStyle.sprites && editingStyle.sprites['1']);
    sCrudaInfo.textContent = has0 ? 'âœ“ Sprite cargado' : 'Sin sprite cargado';
    sCocidaInfo.textContent = has1 ? 'âœ“ Sprite cargado' : 'Sin sprite cargado';
  }

  function openStyle(s){
    closeAllPanels(); isNewStyle=!s;
    editingStyle = s ? JSON.parse(JSON.stringify(s)) : {
      id: null,
      name: '',
      wcm: 27,
      hcm: 27,
      ar: 1,
      shape: 'circle',
      sauceInset: { x: 0.12, y: 0.12 },
      doughBox: { x0: 0, y0: 0, x1: 1, y1: 1 },
      sprites: { '0': '', '1': '' }
    };
    if(!editingStyle.sprites) editingStyle.sprites = { '0': '', '1': '' };
    if(!editingStyle.sauceInset) editingStyle.sauceInset = { x: 0.12, y: 0.12 };

    styleTitle.textContent = isNewStyle ? 'Nuevo estilo de pizza' : 'Editar estilo';
    sName.value = editingStyle.name || '';
    sWcm.value = editingStyle.wcm || 27;
    sHcm.value = editingStyle.hcm || 27;
    sShape.value = editingStyle.shape || 'circle';
    sSauceX.value = Math.round((editingStyle.sauceInset.x ?? 0.12) * 1000) / 10;
    sSauceY.value = Math.round((editingStyle.sauceInset.y ?? 0.12) * 1000) / 10;
    sDelete.style.display = isNewStyle ? 'none' : '';

    stylePrevBake = 1;
    document.querySelectorAll('#sPrevBakeSeg button').forEach(b=>b.classList.toggle('sel', +b.dataset.bake===stylePrevBake));
    updateStyleSpriteStatus();
    drawStylePreview(editingStyle);
    stylePanel.classList.add('show');
  }

  function saveStyle(){
    if(!editingStyle) return;
    const nm = sName.value.trim();
    if(!nm){ toast('Ponele un nombre al estilo'); return; }
    const wcm = parseFloat(sWcm.value) || 27;
    const hcm = parseFloat(sHcm.value) || 27;
    const shape = sShape.value || 'circle';
    const sx = Math.max(0, Math.min(0.4, (parseFloat(sSauceX.value) || 12) / 100));
    const sy = Math.max(0, Math.min(0.4, (parseFloat(sSauceY.value) || 12) / 100));

    editingStyle.name = nm;
    editingStyle.wcm = wcm;
    editingStyle.hcm = hcm;
    editingStyle.ar = wcm / hcm;
    editingStyle.shape = shape;
    editingStyle.sauceInset = { x: sx, y: sy };
    if(!editingStyle.doughBox) editingStyle.doughBox = { x0: 0, y0: 0, x1: 1, y1: 1 };

    if(isNewStyle){
      editingStyle.id = uidIn(nm, STYLES, 'estilo');
      STYLES.push(editingStyle);
    } else {
      editingStyle.id = editingStyle.id || uidIn(nm, STYLES, 'estilo');
      const i = STYLES.findIndex(x => x.id === editingStyle.id);
      if(i >= 0) STYLES[i] = editingStyle; else STYLES.push(editingStyle);
    }
    saveLib(); closeAllPanels(); renderMain(); toast('Estilo de pizza guardado');
  }

  function delStyle(){
    if(!editingStyle || isNewStyle) return;
    if(!confirm('Â¿Eliminar el estilo "' + editingStyle.name + '"?')) return;
    STYLES = STYLES.filter(x => x.id !== editingStyle.id);
    saveLib(); closeAllPanels(); renderMain(); toast('Estilo eliminado');
  }

  // --- wiring ---
  document.querySelectorAll('#modeSeg button').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));
  $('btnNew').onclick=()=>{ if(mode==='driz')openDriz(null); else if(mode==='base')openBase(null); else if(mode==='style')openStyle(null); else openEdit(null); };
  $('search').oninput=renderMain;

  // drizzle panel
  $('closeDriz').onclick=closeAllPanels; $('dSave').onclick=saveDriz; $('dDelete').onclick=delDriz;
  $('dName').oninput=e=>{ if(editingDriz){ editingDriz.name=e.target.value; } };
  $('dColor').oninput=e=>{ if(editingDriz){ editingDriz.color=e.target.value; $('dColorHex').value=e.target.value; drawDrizPreview(editingDriz); } };
  $('dColorHex').oninput=e=>{ if(editingDriz){ const v=e.target.value.trim(); editingDriz.color=v; if(/^#[0-9a-fA-F]{6}$/.test(v)){ $('dColor').value=v; drawDrizPreview(editingDriz);} } };
  $('dAlpha').oninput=e=>{ if(editingDriz){ editingDriz.alpha=parseFloat(e.target.value); $('dAlphaOut').textContent=Math.round(editingDriz.alpha*100)+'%'; drawDrizPreview(editingDriz);} };

  // base panel
  $('closeBase').onclick=closeAllPanels; $('bSave').onclick=saveBase; $('bDelete').onclick=delBase;
  document.querySelectorAll('#bTypeSeg button').forEach(b=>b.addEventListener('click',()=>setBaseType(b.dataset.type)));
  $('bName').oninput=e=>{ if(editingBase){ editingBase.name=e.target.value; } };
  $('bColor').oninput=e=>{ if(editingBase){ editingBase.color=e.target.value; $('bColorHex').value=e.target.value; drawBasePreview(editingBase); } };
  $('bColorHex').oninput=e=>{ if(editingBase){ const v=e.target.value.trim(); editingBase.color=v; if(/^#[0-9a-fA-F]{6}$/.test(v)){ $('bColor').value=v; drawBasePreview(editingBase);} } };
  $('bAlpha').oninput=e=>{ if(editingBase){ editingBase.alpha=parseFloat(e.target.value); $('bAlphaOut').textContent=Math.round(editingBase.alpha*100)+'%'; drawBasePreview(editingBase);} };
  $('bTexUpload').onclick=()=>$('fileTex').click();
  $('bTexClear').onclick=()=>{ if(editingBase){ editingBase.tex=null;     _bTexImg=null; _bSpriteImg=null;
    if(editingBase.sprite){ _bSpriteImg=new Image(); _bSpriteImg.onload=()=>drawBasePreview(editingBase); _bSpriteImg.src=editingBase.sprite; }
    if(editingBase.sprite){ setBaseType('sprite'); } setBaseType('color'); } };
  $('fileTex').onchange=function(){ const f=this.files[0]; this.value=''; if(!f||!editingBase) return;
    const r=new FileReader(); r.onload=()=>{ editingBase.tex=r.result; _bTexImg=new Image();
      _bTexImg.onload=()=>{ setBaseType('tex'); drawBasePreview(editingBase); }; _bTexImg.src=r.result; }; r.readAsDataURL(f); };

  renderMain();
})();
</script>
</body>
</html>
